import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for RNN operations
rnn_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void rnn_kernel(const float* x, const float* hidden, const float* i2h_weight, const float* i2h_bias,
                           const float* h2o_weight, const float* h2o_bias, float* new_hidden, float* output,
                           int input_size, int hidden_size, int output_size, int batch_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * hidden_size) {
        int batch_idx = idx / hidden_size;
        int hidden_idx = idx % hidden_size;

        float sum = 0.0f;
        for (int i = 0; i < input_size; ++i) {
            sum += x[batch_idx * input_size + i] * i2h_weight[hidden_idx * (input_size + hidden_size) + i];
        }
        for (int i = 0; i < hidden_size; ++i) {
            sum += hidden[batch_idx * hidden_size + i] * i2h_weight[hidden_idx * (input_size + hidden_size) + input_size + i];
        }
        sum += i2h_bias[hidden_idx];
        new_hidden[idx] = tanhf(sum);
    }

    if (idx < batch_size * output_size) {
        int batch_idx = idx / output_size;
        int output_idx = idx % output_size;

        float sum = 0.0f;
        for (int i = 0; i < hidden_size; ++i) {
            sum += new_hidden[batch_idx * hidden_size + i] * h2o_weight[output_idx * hidden_size + i];
        }
        sum += h2o_bias[output_idx];
        output[idx] = sum;
    }
}

torch::Tensor rnn_cuda(torch::Tensor x, torch::Tensor hidden, torch::Tensor i2h_weight, torch::Tensor i2h_bias,
                       torch::Tensor h2o_weight, torch::Tensor h2o_bias) {
    int batch_size = x.size(0);
    int input_size = x.size(1);
    int hidden_size = hidden.size(1);
    int output_size = h2o_weight.size(0);

    auto new_hidden = torch::zeros_like(hidden);
    auto output = torch::zeros({batch_size, output_size}, x.options());

    const int block_size = 256;
    const int num_blocks = (batch_size * hidden_size + block_size - 1) / block_size;

    rnn_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), hidden.data_ptr<float>(),
                                           i2h_weight.data_ptr<float>(), i2h_bias.data_ptr<float>(),
                                           h2o_weight.data_ptr<float>(), h2o_bias.data_ptr<float>(),
                                           new_hidden.data_ptr<float>(), output.data_ptr<float>(),
                                           input_size, hidden_size, output_size, batch_size);

    return new_hidden;
}
"""

rnn_cpp_source = (
    "torch::Tensor rnn_cuda(torch::Tensor x, torch::Tensor hidden, torch::Tensor i2h_weight, torch::Tensor i2h_bias, "
    "torch::Tensor h2o_weight, torch::Tensor h2o_bias);"
)

# Compile the inline CUDA code for RNN operations
rnn_cuda = load_inline(
    name="rnn_cuda",
    cpp_sources=rnn_cpp_source,
    cuda_sources=rnn_kernel_source,
    functions=["rnn_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size
        self.hidden = torch.randn((batch_size, hidden_size))

        # Define the RNN cell components (input to hidden, hidden to hidden, and hidden to output)
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)  # Input to hidden
        self.h2o = nn.Linear(hidden_size, output_size)  # Hidden to output
        self.rnn_cuda = rnn_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        self.hidden = self.hidden.to(x.device)
        self.hidden = self.rnn_cuda.rnn_cuda(x, self.hidden, self.i2h.weight, self.i2h.bias, self.h2o.weight, self.h2o.bias)
        return self.hidden
